head.script:
// elw발행사

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        txb_ISUR_NM.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90800.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        const ISUR_CD = dts_List.getCellData(row, "ISUR_CD");
        const COM_NM = dts_List.getCellData(row, "COM_NM");
        const WRNT_ISUR_CD = dts_List.getCellData(row, "WRNT_ISUR_CD");
        const WRNT_ISUR_NM = dts_List.getCellData(row, "WRNT_ISUR_NM");
        $c.frame.path("../").ins_popupRtn_val4(ISUR_CD, COM_NM, WRNT_ISUR_CD, WRNT_ISUR_NM);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90800.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90800.btn_close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90800.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90800.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.ins_search(txb_ISUR_NM.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90800.btn_search_onclick" });
    }
};

/**
 * @method
 * @name txb_ISUR_NM_onkeyup
 * @description txb_ISUR_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_ISUR_NM_onkeyup = async function() {
    try {
        fn_DelChar(this);
        if (txb_ISUR_NM.getValue() === "") {

        } else {
            if (window.event.keyCode === 13) {
                await scwin.ins_search(txb_ISUR_NM.getValue());
            } else {

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90800.txb_ISUR_NM_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description elw발행사  조회 한다.
 * @param {*} isurnm isurnm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function(isurnm) {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
